codeExamples.code:
# 1) Set default SSE-KMS on the bucket with an S3 Bucket Key (cuts KMS calls)
cat > enc.json <<'JSON'
{
  "Rules": [{
    "ApplyServerSideEncryptionByDefault": {
      "SSEAlgorithm": "aws:kms",
      "KMSMasterKeyID": "alias/etl-data"
    },
    "BucketKeyEnabled": true
  }]
}
JSON
aws s3api put-bucket-encryption \
  --bucket data-eng-orders-prod \
  --server-side-encryption-configuration file://enc.json

# 2) Upload an object (encrypted transparently with alias/etl-data)
aws s3 cp ./orders.parquet s3://data-eng-orders-prod/curated/orders.parquet

# 3) Key policy statement: only EtlRole may use the key, scoped by context
cat <<'JSON'
{
  "Sid": "AllowEtlRoleUse",
  "Effect": "Allow",
  "Principal": { "AWS": "arn:aws:iam::111122223333:role/EtlRole" },
  "Action": ["kms:GenerateDataKey", "kms:Decrypt", "kms:DescribeKey"],
  "Resource": "*",
  "Condition": {
    "StringEquals": { "kms:EncryptionContext:pipeline": "orders" }
  }
}
JSON
